import{_ as n,C as t,o as s,c as i,E as r,a2 as l}from"./chunks/framework.BOeh4kYD.js";const p="/joinwell52/assets/current-context-20260916/session-without-old-keys.figure.zh.svg",f=JSON.parse('{"title":"会话恢复了，旧密钥也该留下吗？","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"会话恢复了，旧密钥也该留下吗？","date":"2026-09-16","published_date":"2026-09-16","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"会话恢复了，旧密钥也该留下吗？","summary":"对话需要记忆，启动它的密钥却不一定需要。真实临时文件的对照还发现：恢复时用上了新值，不代表旧文件里的旧值已经消失。","cover":"/assets/current-context-20260916/session-without-old-keys.cover-v1.png","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"evidence_status":"固定源码有界实验；范围见正文","pageClass":"current-context-article"},"headers":[],"relativePath":"zh/engineering/2026-09-16-session-without-old-keys.md","filePath":"zh/engineering/2026-09-16-session-without-old-keys.md","lastUpdated":1789531953000}'),d={name:"zh/engineering/2026-09-16-session-without-old-keys.md"};function c(h,e,u,g,m,_){const a=t("ArticleCover"),o=t("ArticleTableScroll");return s(),i("div",null,[r(a,{image:"/assets/current-context-20260916/session-without-old-keys.cover-v1.png",kicker:"开源工程观察 · 实验研究",title:"会话恢复了，旧密钥也该留下吗？",summary:"对话需要记忆，启动它的密钥却不一定需要。真实临时文件的对照还发现：恢复时用上了新值，不代表旧文件里的旧值已经消失。",version:"2026-09-16",languageHref:"/en/engineering/2026-09-16-session-without-old-keys",languageLabel:"English"}),r(o,{language:"zh"}),e[0]||(e[0]=l('<h1 id="会话恢复了-旧密钥也该留下吗" tabindex="-1">会话恢复了，旧密钥也该留下吗？ <a class="header-anchor" href="#会话恢复了-旧密钥也该留下吗" aria-label="Permalink to &quot;会话恢复了，旧密钥也该留下吗？&quot;">​</a></h1><p>保存一段 AI 会话，是为了明天还能接着做。对话历史需要留下，这很容易理解。</p><p>但启动助手时用过的密钥，也需要跟着留下吗？</p><p>这里的密钥，是程序访问服务时使用的凭证。换了账号或连接配置，当前运行可能已经改用新凭证。<strong>我们用真实临时文件做实验，却看到一种容易被忽略的状态：恢复已经用上新值，旧值仍躺在磁盘文件里。</strong></p><p>“现在能继续工作了”，回答不了“以前的副本清理了吗”。</p><h2 id="为什么会话记录里会混入密钥" tabindex="-1">为什么会话记录里会混入密钥？ <a class="header-anchor" href="#为什么会话记录里会混入密钥" aria-label="Permalink to &quot;为什么会话记录里会混入密钥？&quot;">​</a></h2><p>问题来自 electrumnz 提交的 <a href="https://github.com/paperclipai/paperclip/pull/13498" target="_blank" rel="noreferrer">Paperclip #13498</a>。Paperclip 是用于组织 AI 助手工作的开源应用；研究时，这份修复提案尚未合入。</p><p>程序启动助手时，会传入一组配置，称为“环境变量”，其中可能包含访问服务所需的密钥。上游指出，这组启动配置跟着会话设置一起写进了文件，于是原本为本次运行准备的凭证，也变成了可长期保留的副本。</p><p>这吸引我们，是因为“为了以后恢复，尽量多存一些”听起来很合理。但历史消息和启动凭证的用途不同：明天需要接着读昨天的对话，并不意味着必须继续使用昨天的凭证。</p><p>候选修复把这两件事拆开：保存时去掉启动环境，恢复时再填入当前运行的环境。我们的研究问题随之变得具体：这样既能保留历史，又能处理磁盘上的旧值吗？</p><h2 id="用假密钥-检查真的文件" tabindex="-1">用假密钥，检查真的文件 <a class="header-anchor" href="#用假密钥-检查真的文件" aria-label="Permalink to &quot;用假密钥，检查真的文件&quot;">​</a></h2><p>实验只用容易识别的合成字符串代替凭证，不读取真实密钥。我们把候选的保存和加载代码接到临时文件上：先准备一个旧值，再用另一个当前值恢复，最后直接查看文件里还剩什么。</p><table tabindex="0"><thead><tr><th>操作</th><th>磁盘是否仍含旧合成值</th><th>恢复时是否使用当前值</th></tr></thead><tbody><tr><td>直接保存未经处理的原记录</td><td>是</td><td>是，加载仍经过候选代码</td></tr><tr><td>经过候选代码保存新记录</td><td><strong>否</strong></td><td>是</td></tr><tr><td>读取已有旧记录，不再保存</td><td><strong>是</strong></td><td>是</td></tr><tr><td>读取旧记录后，再经过候选代码保存</td><td><strong>否</strong></td><td>是</td></tr></tbody></table><p>四个场景都保留了对话历史。保存时传入的原始对象也没有被修改：去掉文件副本里的环境，没有顺手破坏运行中仍可能需要的内存数据。</p><p>这张表里最值得停一下的是第三行。恢复拿到了当前值，磁盘检查却仍找到了旧值。两项检查都没看错，它们看的是不同地方。</p><p><img src="'+p+'" alt="磁盘记录与当前运行的凭证分离"></p><p><em>图 1：加载时使用新值，与保存时移除旧环境，作用在不同位置。来源：本轮真实临时文件实验，由作者绘制。</em></p><h2 id="为什么读过旧文件-旧值还在" tabindex="-1">为什么读过旧文件，旧值还在？ <a class="header-anchor" href="#为什么读过旧文件-旧值还在" aria-label="Permalink to &quot;为什么读过旧文件，旧值还在？&quot;">​</a></h2><p>因为读文件和改文件，本来就是两个动作。</p><p>候选代码读取旧记录后，给当前运行返回一份换上新环境的对象。它没有在读取期间重写原文件。我们随后明确再保存一次，受测位置里的旧值才消失。</p><p>这符合提案中“再次保存后移除环境字段”的说明。对升级软件的人而言，还有一件事要说清：那些以后不再打开、不再保存的旧记录，准备怎样处理？备份里如果还有旧副本，又由谁处理？</p><p>修复已经阻止了新保存记录继续带上启动环境，也让恢复采用当前环境。实验帮助我们看清的是，它与“把已有副本全部清理完”之间，还隔着一项升级工作。</p><h2 id="旧副本清了-旧凭证就不能用了吗" tabindex="-1">旧副本清了，旧凭证就不能用了吗？ <a class="header-anchor" href="#旧副本清了-旧凭证就不能用了吗" aria-label="Permalink to &quot;旧副本清了，旧凭证就不能用了吗？&quot;">​</a></h2><p>还不能这样推断。“旧”只表示它是以前使用的值，不表示服务端已经让它失效。删除本机的一份记录，也不等于吊销那段凭证。</p><p>所以开发者需要分别回答三问：</p><ul><li><strong>今后还会不会写入？</strong> 检查新保存的记录。</li><li><strong>以前留下的副本怎么办？</strong> 明确旧会话文件和备份的处理责任。</li><li><strong>不该继续有效的凭证是否已失效？</strong> 这需要凭证管理，不能靠删除文件来代替。</li></ul><p>本轮实验回答了受测保存与加载路径的行为，没有执行凭证轮换、吊销或备份清理。</p><p>对普通使用者，这也可以变成一个具体反馈：更换账号或连接以后，软件是否说明了哪些历史会保留、旧连接材料怎样处理？恢复成功当然有用，但它不应该让人误以为所有旧副本也已处理完。</p><p>我们由此向维护者提出的追问是：能否把“阻止新写入”和“处理既有记录”的区别写进升级说明，并明确后者的责任？这个问题关系到修复如何被正确使用，而不仅是保存函数怎样写。</p><details><summary>给技术读者：过滤范围、第五个对照与实验边界</summary><p>来源作者 electrumnz；研究时 #13498 仍 OPEN。固定候选 <code>bfe7f568976a2c671184722a6e6294927d6e6fae</code>，来源基线 <code>9cfa7fd2d13213b73396cf34b9fc95912857ff69</code>。</p><p>运行候选完整 <code>session-store.ts</code>：它包装存储接口，在 save 时移除 <code>acpx.session_options.env</code>，在 load 时放入本次的 launchEnv。底层使用我们实现的真实临时 JSON 文件存储。直接保存原记录是反例对照，不称为完整旧 ACPX 实现。</p><p>第五个边界场景故意把同一个合成值放进无关的 debug 字段。候选移除了指定环境字段，却保留那个任意字段中的值。这验证它是针对已知结构的过滤，不是通用敏感值扫描器；人工字段不能证明生产系统另有泄露路径。</p><p>上游讨论了同一操作系统账号下多个助手席位的访问风险，也提出关闭 shell 快照的改动。我们没有复现这些路径，没有启动真实 ACPX 子进程，也没有验证跨席位访问、备份清理、凭证轮换或完整产品恢复。上游报告的 195 项测试不计入我们的实测数量。</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-16-current-context" target="_blank" rel="noreferrer">五个场景的原始观察、探针与固定源码</a>。没有据此断言 CodeFlowMu 存在相同泄露。</p></details><p><a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">研究仓库</a></p>',31))])}const k=n(d,[["render",c]]);export{f as __pageData,k as default};
